={
  "script": {
    "source": "ctx._source.aprobaciones.add(params.aprobacion)",
    "params": {
      "aprobacion": {
        "etapa": {{ parseInt($('Elasticsearch2').first().json.etapa)-1 }},
        "proceso": "{{ $('Get row(s) in sheet').first().json.Proceso }}",
        "email_usuario": "{{ $('Get row(s) in sheet').first().json.Email }}",
        "nombre_usuario": "{{ $('Get row(s) in sheet').first().json.Nombre }}",
        "fecha": "{{ $now }}",
        "status":"Aprobada"
      }
    }
  }
}

